import { Controller, Get, Post, HttpCode, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

const DEFAULT_SIZE = 20;
const MAX_SIZE = 200;
const STATUSES = ['기안', '결재대기', '승인', '보류', '반려', '회수', '재기안', '완료'];
// 가정: 반려 사유가 없으면 422 REJECT_REASON_REQUIRED로 처리를 보류한다.

const LIST_WHERE = `
  WHERE (CAST(:projectId AS bigint) IS NULL OR project_id = CAST(:projectId AS bigint))
    AND (CAST(:budgetAccountId AS bigint) IS NULL OR budget_account_id = CAST(:budgetAccountId AS bigint))
    AND (CAST(:status AS varchar) IS NULL OR status = CAST(:status AS varchar))
    AND (CAST(:createdFrom AS date) IS NULL OR created_at >= CAST(:createdFrom AS date))
    AND (CAST(:createdTo AS date) IS NULL OR created_at < CAST(:createdTo AS date) + 1)
`;

function isEmpty(value: unknown): boolean {
  return value === undefined || value === null || value === '';
}

function optionalId(value: unknown): string | null {
  if (isEmpty(value)) {
    return null;
  }
  const text = String(value);
  if (!/^\d+$/.test(text)) {
    throw new ApiError(400, 'VALIDATION_FAILED', '조회 조건의 ID 형식이 올바르지 않습니다.');
  }
  return text;
}

function optionalDate(value: unknown): string | null {
  if (isEmpty(value)) {
    return null;
  }
  const text = String(value);
  if (!/^\d{4}-\d{2}-\d{2}$/.test(text)) {
    throw new ApiError(400, 'VALIDATION_FAILED', '날짜는 YYYY-MM-DD 형식으로 입력해 주세요.');
  }
  return text;
}

function optionalInt(value: unknown, fallback: number, name: string): number {
  if (isEmpty(value)) {
    return fallback;
  }
  const text = String(value);
  if (!/^\d+$/.test(text)) {
    throw new ApiError(400, 'VALIDATION_FAILED', name + ' 값이 올바르지 않습니다.');
  }
  return Number(text);
}

@Controller('api/v1')
export class FnSfr02402Controller {
  @Get('/requisitions')
  async listRequisitions(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원', '예산·회계 담당자', '시스템 관리자');
    const query = checks.queryOf(req.query);
    const projectId = optionalId(query['projectId']);
    const budgetAccountId = optionalId(query['budgetAccountId']);
    const createdFrom = optionalDate(query['createdFrom']);
    const createdTo = optionalDate(query['createdTo']);
    let status: string | null = null;
    if (!isEmpty(query['status'])) {
      status = String(query['status']);
      if (!STATUSES.includes(status)) {
        throw new ApiError(400, 'VALIDATION_FAILED', '처리 상태 값이 올바르지 않습니다.');
      }
    }
    const page = optionalInt(query['page'], 0, 'page');
    let size = optionalInt(query['size'], DEFAULT_SIZE, 'size');
    if (size < 1) {
      size = DEFAULT_SIZE;
    }
    if (size > MAX_SIZE) {
      size = MAX_SIZE;
    }
    return transaction(async (db) => {
      const filter = { projectId, budgetAccountId, status, createdFrom, createdTo };
      const counted = await db.query(
        `SELECT CAST(COUNT(*) AS integer) AS "total" FROM requisition ${LIST_WHERE}`,
        filter,
      );
      const items = await db.query(
        `SELECT requisition_id AS "requisitionId",
                project_id AS "projectId",
                budget_account_id AS "budgetAccountId",
                title AS "title",
                requisition_amount AS "requisitionAmount",
                status AS "status",
                created_at AS "createdAt"
           FROM requisition ${LIST_WHERE}
          ORDER BY created_at DESC, requisition_id DESC
          LIMIT CAST(:size AS integer) OFFSET CAST(:offset AS integer)`,
        { ...filter, size, offset: page * size },
      );
      const total = counted.length > 0 ? Number(counted[0]['total']) : 0;
      return { items, page, size, total };
    });
  }

  @Post('/requisitions/:requisitionId/reject')
  @HttpCode(200)
  async rejectRequisition(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원', '예산·회계 담당자', '시스템 관리자');
    const data = checks.inputOf(req.body);
    const requisitionId = req.params['requisitionId'];
    const reason = data['rejectReason'];
    if (typeof reason !== 'string' || reason.trim() === '') {
      throw new ApiError(422, 'REJECT_REASON_REQUIRED', '반려 사유를 입력해 주세요.');
    }
    if (!/^\d+$/.test(requisitionId)) {
      throw new ApiError(404, 'REQUISITION_NOT_FOUND', '구매품의를 찾을 수 없습니다.');
    }
    return transaction(async (db) => {
      const rows = await db.query(
        `SELECT status AS "status"
           FROM requisition
          WHERE requisition_id = CAST(:requisitionId AS bigint)
            FOR UPDATE`,
        { requisitionId },
      );
      if (rows.length === 0) {
        throw new ApiError(404, 'REQUISITION_NOT_FOUND', '구매품의를 찾을 수 없습니다.');
      }
      if (rows[0]['status'] !== '결재대기') {
        throw new ApiError(409, 'REQUISITION_STATUS_MISMATCH', '결재대기 상태의 구매품의만 반려할 수 있습니다.');
      }
      const changed = await db.query(
        `UPDATE requisition
            SET status = '반려', updated_at = now()
          WHERE requisition_id = CAST(:requisitionId AS bigint)
        RETURNING status AS "status"`,
        { requisitionId },
      );
      return { status: changed[0]['status'] };
    });
  }
}

