import { useState } from 'react';
import {
  call,
  useData,
  Badge,
  Num,
  Filters,
  Band,
  DataTable,
  Pager,
  Drawer,
  Pairs,
  Form,
  Field,
  TextInput,
  Select,
  LookupSelect,
  RefName,
  ErrorText,
} from '../kit';
import type { PageProps, Row, Page, Column } from '../kit';

const SIZE = 20;
const STATUS_OPTIONS: [string, string][] = [
  ['기안', '기안'],
  ['결재대기', '결재대기'],
  ['승인', '승인'],
  ['보류', '보류'],
  ['반려', '반려'],
  ['회수', '회수'],
  ['재기안', '재기안'],
  ['완료', '완료'],
];

export default function FnSfr02402Page({ role, notify }: PageProps) {
  const [draft, setDraft] = useState<Row>({});
  const [applied, setApplied] = useState<Row>({});
  const [pageNo, setPageNo] = useState(0);
  const [selectedId, setSelectedId] = useState<number | null>(null);
  const [drawer, setDrawer] = useState<'' | 'approve' | 'reject'>('');
  const [rejectReason, setRejectReason] = useState('');

  const list = useData<Page>(
    () => call<Page>('GET', '/requisitions', role, undefined, { ...applied, page: pageNo, size: SIZE }),
    [applied, pageNo],
  );
  const detail = useData<Row | undefined>(
    () => (selectedId === null
      ? Promise.resolve(undefined)
      : call<Row>('GET', '/requisitions/' + selectedId, role)),
    [selectedId],
  );

  const columns: Column[] = [
    { key: 'title', label: '품의 제목' },
    { key: 'projectId', label: '프로젝트', render: (r) => <RefName table="project" role={role} value={r['projectId']} /> },
    { key: 'budgetAccountId', label: '예산과목', render: (r) => <RefName table="budget_account" role={role} value={r['budgetAccountId']} /> },
    { key: 'requisitionAmount', label: '품의 금액', render: (r) => <Num value={r['requisitionAmount']} /> },
    { key: 'status', label: '처리 상태', render: (r) => <Badge value={r['status']} /> },
  ];

  function search() {
    setPageNo(0);
    setApplied({ ...draft });
  }

  function reset() {
    setDraft({});
    setPageNo(0);
    setApplied({});
  }

  function closeDrawer() {
    setDrawer('');
    setRejectReason('');
  }

  function refresh() {
    list.reload();
    detail.reload();
  }

  async function approve() {
    await call('POST', '/requisitions/' + selectedId + '/approve', role, {});
    notify('구매품의를 승인했습니다.');
    closeDrawer();
    refresh();
  }

  async function reject() {
    if (rejectReason.trim() === '') {
      throw new Error('반려 사유를 입력해 주세요.');
    }
    await call('POST', '/requisitions/' + selectedId + '/reject', role, { rejectReason });
    notify('구매품의를 반려했습니다.');
    closeDrawer();
    refresh();
  }

  if (selectedId !== null) {
    const row = detail.data;
    return (
      <div className="doc">
        <button className="ghost" onClick={() => { setSelectedId(null); closeDrawer(); }}>목록으로 돌아가기</button>
        {detail.error && <ErrorText text={detail.error} />}
        {row && (
          <>
            <section className="box">
              <h2>품의 내용</h2>
              <Pairs
                items={[
                  ['품의 제목', String(row['title'] ?? '')],
                  ['프로젝트', <RefName table="project" role={role} value={row['projectId']} />],
                  ['예산과목', <RefName table="budget_account" role={role} value={row['budgetAccountId']} />],
                  ['품의 금액', <Num value={row['requisitionAmount']} />],
                  ['품의 내용', String(row['content'] ?? '')],
                  ['처리 상태', <Badge value={row['status']} />],
                ]}
              />
            </section>
            {row['status'] === '결재대기' && (
              <section className="box">
                <h2>승인 처리</h2>
                <p>결재대기 상태의 구매품의를 승인하거나 반려할 수 있습니다.</p>
                <button onClick={() => setDrawer('approve')}>승인</button>
                <button className="ghost" onClick={() => setDrawer('reject')}>반려</button>
              </section>
            )}
          </>
        )}
        {drawer === 'approve' && (
          <Drawer title="구매품의 승인" onClose={closeDrawer}>
            <Form
              onSubmit={approve}
              submit="승인"
              note="승인하면 처리 상태가 승인으로 바뀌고, 승인 취소 절차 없이는 수정할 수 없습니다."
            />
          </Drawer>
        )}
        {drawer === 'reject' && (
          <Drawer title="구매품의 반려" onClose={closeDrawer}>
            <Form
              onSubmit={reject}
              submit="반려"
              danger
              note="반려하면 처리 상태가 반려로 바뀌며 되돌릴 수 없습니다."
            >
              <Field label="반려 사유" required wide>
                <TextInput value={rejectReason} onChange={setRejectReason} multiline />
              </Field>
            </Form>
          </Drawer>
        )}
      </div>
    );
  }

  const data = list.data;
  return (
    <div className="doc">
      <h1>구매품의 조회 및 승인</h1>
      <Filters onSearch={search} onReset={reset}>
        <Field label="프로젝트">
          <LookupSelect
            table="project"
            role={role}
            value={draft['projectId']}
            onChange={(v) => setDraft({ ...draft, projectId: v })}
          />
        </Field>
        <Field label="예산과목">
          <LookupSelect
            table="budget_account"
            role={role}
            value={draft['budgetAccountId']}
            onChange={(v) => setDraft({ ...draft, budgetAccountId: v })}
          />
        </Field>
        <Field label="처리 상태">
          <Select
            value={draft['status']}
            onChange={(v) => setDraft({ ...draft, status: v })}
            options={STATUS_OPTIONS}
          />
        </Field>
      </Filters>
      {list.error && <ErrorText text={list.error} />}
      <Band total={data?.total} />
      <DataTable
        columns={columns}
        rows={data?.items ?? []}
        onRowClick={(r) => setSelectedId(Number(r['requisitionId']))}
        empty="조건에 맞는 구매품의가 없습니다. 조회 조건을 바꿔 다시 조회해 보세요."
      />
      <Pager page={pageNo} size={SIZE} total={data?.total ?? 0} onPage={setPageNo} />
    </div>
  );
}
